<?php
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * The points ("тезисы") of an infographic picture, and fitting them into a
 * preset. Same as WPPF_Infographic in wp-pinfeed.
 *
 * Where the points come from, first hit wins:
 *  1) by hand — the "Тезисы для инфографики" field in the post's Telegram box;
 *  2) the model — generated by the background tick before the message is
 *     sent, cached per post. The post's own structure («Коротко», H2,
 *     lists) is only *context* for the model, never a source of points:
 *     headings and raw list items don't make a good infographic.
 * No points (no model keys, an error, too little text) means no infographic:
 * the channel's fallback decides (text with a link preview, or skip).
 *
 * Fitting follows llm-agent-articles: text is never cut. In the background,
 * points that overflow their block are rewritten shorter by the model; at
 * render time whatever still overflows is dropped as a whole point, longest
 * first, down to three.
 */
class WPTP_Infographic {

	const META        = '_wptp_theses';
	const MAX_ENTRIES = 6;
	const MIN_POINTS  = 3;

	const SYSTEM_PROMPT = <<<'PROMPT'
Ты редактор. Из материала делаешь тезисы для инфографики к посту в Telegram-канале.

Верни СТРОГО JSON-объект (без markdown-обёртки, без пояснений вокруг):
{
  "points": [
    {"label": "1-3 слова — о чём пункт", "text": "законченная мысль одним предложением"}
  ]
}

Правила:
— Ровно столько пунктов, сколько попрошено.
— Каждый пункт — отдельная полезная мысль: шаг, совет, факт, возможность. Пункты не пересказывают друг друга.
— text — законченное предложение, понятное без статьи, без «см. выше».
— Жёстко соблюдай предел длины text — считай символы.
— label — существительное или короткая именная группа, без точки.
— Порядок логичный: от первого шага к последнему или от главного к частному.
— Без эмодзи, штампов и восклицательных знаков. Не выдумывай факты, цифры и названия, которых нет в материале.
PROMPT;

	const SHORTEN_PROMPT = 'Ты редактор. Перепиши тезис короче, сохранив смысл и ключевые слова. Это не обрезка — новая формулировка, законченное предложение. Ответ — строго JSON {"text": "..."}.';

	/** Headings that are navigation, not content — never a point. */
	const SERVICE_HEADINGS = '/^(коротко|кратко|главное|содержание|оглавление|частые вопросы|вопросы и ответы|faq|читайте также|см\.? также|заключение|выводы?|итоги?|источники|ссылки|references|table of contents|contents|license|лицензия|contributing|changelog)\b/iu';

	/** Headings above a list that summarises the post. */
	const SUMMARY_HEADINGS = '/^(коротко|кратко|главное|ключевые (мысли|выводы|тезисы)|в двух словах|tl;?dr|key takeaways|summary|highlights|features|возможности|особенности)/iu';

	// --------------------------------------------------------------- points

	/**
	 * @return array{state:string,points:array,source:string,reason:string}
	 *         state: ready | pending (the model hasn't answered yet) | none
	 */
	public static function points_for( WP_Post $post, array $config ) {
		$count = self::count( $config );

		$manual = self::manual_points( $post );
		if ( count( $manual ) >= self::MIN_POINTS ) {
			return self::ready( $manual, $count, 'manual' );
		}

		$cached = self::cached( $post, $config );
		if ( $cached ) {
			return self::ready( $cached, $count, 'llm' );
		}

		$reason = self::llm_blocker( $post, $config );
		return array(
			'state'  => '' === $reason ? 'pending' : 'none',
			'points' => array(),
			'source' => 'llm',
			'reason' => $reason,
		);
	}

	public static function count( array $config ) {
		return max( self::MIN_POINTS, min( 8, (int) $config['infographic_points'] ) );
	}

	private static function ready( array $points, $count, $source ) {
		return array(
			'state'  => 'ready',
			'points' => array_slice( $points, 0, $count ),
			'source' => $source,
			'reason' => '',
		);
	}

	public static function manual_points( WP_Post $post ) {
		$raw = (string) get_post_meta( $post->ID, WPTP_Post_Meta::THESES, true );
		$out = array();
		foreach ( preg_split( "/\r\n|\n|\r/", $raw ) as $line ) {
			$point = self::split_label( $line );
			if ( $point ) {
				$out[] = $point;
			}
		}
		return $out;
	}

	/**
	 * The post's own summary/heading structure — context for the model's
	 * prompt only, never served as points.
	 *
	 * @return array{points:array,source:string}
	 */
	public static function from_structure( WP_Post $post ) {
		$html = (string) $post->post_content;

		// 1) A summary list right under a summary heading — «Коротко» first.
		if ( preg_match_all( '#<h([2-4])([^>]*)>(.*?)</h\1>\s*(?:<!--.*?-->\s*)*<(ul|ol)[^>]*>(.*?)</\4>#isu', $html, $m, PREG_SET_ORDER ) ) {
			foreach ( $m as $set ) {
				$heading = self::text( $set[3] );
				if ( false !== strpos( $set[2], 'korotko' ) || preg_match( self::SUMMARY_HEADINGS, $heading ) ) {
					$points = self::list_points( $set[5] );
					if ( count( $points ) >= self::MIN_POINTS ) {
						return array( 'points' => $points, 'source' => 'summary' );
					}
				}
			}
		}

		// 2) Section headings.
		if ( preg_match_all( '#<h2[^>]*>(.*?)</h2>#isu', $html, $m ) ) {
			$points = array();
			foreach ( $m[1] as $heading ) {
				$text = self::text( $heading );
				if ( '' === $text || preg_match( self::SERVICE_HEADINGS, $text ) || mb_strlen( $text ) > 160 ) {
					continue;
				}
				$points[] = array( 'label' => '', 'text' => $text );
			}
			if ( count( $points ) >= self::MIN_POINTS ) {
				return array( 'points' => $points, 'source' => 'headings' );
			}
		}

		// 3) The longest reasonable bullet list.
		$best = array();
		if ( preg_match_all( '#<(ul|ol)[^>]*>(.*?)</\1>#isu', $html, $m ) ) {
			foreach ( $m[2] as $inner ) {
				$points = self::list_points( $inner );
				if ( count( $points ) > count( $best ) && count( $points ) <= 12 ) {
					$best = $points;
				}
			}
		}
		return array( 'points' => count( $best ) >= self::MIN_POINTS ? $best : array(), 'source' => 'list' );
	}

	private static function list_points( $inner_html ) {
		$out = array();
		if ( ! preg_match_all( '#<li[^>]*>(.*?)</li>#isu', $inner_html, $m ) ) {
			return $out;
		}
		foreach ( $m[1] as $li ) {
			// "<strong>Label</strong> — text" → label + text.
			if ( preg_match( '#^\s*<(strong|b)>(.*?)</\1>\s*[:—–-]?\s*(.+)$#isu', $li, $parts ) ) {
				$label = self::text( $parts[2] );
				$text  = self::text( $parts[3] );
				if ( '' !== $text && mb_strlen( $label ) <= 40 ) {
					$out[] = array( 'label' => rtrim( $label, ':.' ), 'text' => $text );
					continue;
				}
			}
			// Only bold text makes a label here: "Частая ошибка — путь…" is one
			// sentence, and splitting it on the dash would change its meaning.
			$text = self::text( $li );
			if ( mb_strlen( $text ) >= 12 && mb_strlen( $text ) <= 260 ) {
				$out[] = array( 'label' => '', 'text' => $text );
			}
		}
		return $out;
	}

	/** "Метка: текст" / "Метка — текст" → label + text; otherwise text only. */
	public static function split_label( $line ) {
		$line = trim( (string) $line, " \t-•*" );
		if ( '' === $line ) {
			return null;
		}
		if ( preg_match( '/^([^:—–]{2,40}?)\s*(?::|\s[—–]\s)\s*(.{8,})$/u', $line, $m ) && count( preg_split( '/\s+/u', trim( $m[1] ) ) ) <= 4 ) {
			return array( 'label' => trim( $m[1] ), 'text' => trim( $m[2] ) );
		}
		return array( 'label' => '', 'text' => $line );
	}

	private static function text( $html ) {
		return trim( preg_replace( '/\s+/u', ' ', WPTP_Template::plain( $html ) ) );
	}

	// ------------------------------------------------------------------ LLM

	public static function config_hash( array $config ) {
		return WPTP_Channel_Config::hash( $config, array( 'infographic_points', 'infographic_preset', 'infographic_title', 'footer_template', 'llm_provider', 'llm_language', 'llm_prompt' ) );
	}

	public static function cached( WP_Post $post, array $config ) {
		$all  = get_post_meta( $post->ID, self::META, true );
		$hash = self::config_hash( $config );
		if ( ! is_array( $all ) || empty( $all[ $hash ] ) || ( $all[ $hash ]['modified'] ?? '' ) !== $post->post_modified_gmt ) {
			return null;
		}
		return (array) $all[ $hash ]['points'];
	}

	/** Below this much text the model can only invent points — better no infographic. */
	const MIN_SOURCE_CHARS = 300;

	/** Why the model can't be asked for this post right now ('' — it can). */
	private static function llm_blocker( WP_Post $post, array $config ) {
		if ( ! WPTP_Settings::llm_ready( $config['llm_provider'] ) ) {
			return 'ключи модели не заполнены';
		}
		if ( get_transient( self::failed_key( $post->ID, $config ) ) ) {
			return 'модель не ответила, повтор через несколько часов';
		}
		$text = WPTP_Template::content_text( $post ) . ' ' . $post->post_excerpt . ' ' . get_post_meta( $post->ID, 'short_description', true );
		if ( mb_strlen( trim( $text ) ) < self::MIN_SOURCE_CHARS ) {
			return 'в записи слишком мало текста для тезисов';
		}
		return '';
	}

	/** Should the background tick ask the model for this post's points? */
	public static function needs_generation( WP_Post $post, array $config ) {
		if ( 'generate' !== $config['image_missing'] || 'photo' !== $config['format'] ) {
			return false;
		}
		// Same decision WPTP_Message_Builder makes: a picture was found — no infographic.
		$pick = WPTP_Image_Resolver::find( $post, $config );
		if ( $pick['found'] ) {
			return false;
		}
		return 'pending' === self::points_for( $post, $config )['state'];
	}

	/** Asks the model, fits the answer to the preset, caches it. */
	public static function generate( WP_Post $post, array $config ) {
		$preset = WPTP_Infographic_Presets::get( $config['infographic_preset'] );
		$count  = self::count( $config );
		$client = new WPTP_LLM_Client( $config['llm_provider'] );

		$parsed = $client->json( self::SYSTEM_PROMPT, self::user_prompt( $post, $config, $count, self::char_budget( $preset, $count ), (bool) $preset['label_enabled'] ), 1600, 0.5 );
		$points = array();
		foreach ( (array) ( is_array( $parsed ) ? ( $parsed['points'] ?? $parsed ) : array() ) as $item ) {
			if ( is_string( $item ) ) {
				$item = array( 'text' => $item );
			}
			if ( is_array( $item ) && ! empty( $item['text'] ) ) {
				$points[] = array(
					'label' => $preset['label_enabled'] ? self::text( (string) ( $item['label'] ?? '' ) ) : '',
					'text'  => self::text( (string) $item['text'] ),
				);
			}
		}

		if ( count( $points ) < self::MIN_POINTS ) {
			WPTP_Log::error( 'Тезисы: запись #' . $post->ID . ' («' . get_the_title( $post ) . '»): ' . ( $client->last_error() ? $client->last_error() : 'модель вернула ' . count( $points ) . ' пунктов' ) );
			set_transient( self::failed_key( $post->ID, $config ), 1, 6 * HOUR_IN_SECONDS );
			return null;
		}
		$points = array_slice( $points, 0, $count );

		// One rewrite pass for points that overflow their block, like articles do.
		$ctx     = array( 'post' => $post, 'config' => $config, 'llm' => WPTP_LLM_Text::cached( $post, $config ) );
		$measure = WPTP_Infographic_Composer::measure( $preset, $points, WPTP_Template::render( $config['infographic_title'], $ctx ), WPTP_Template::render( $config['footer_template'], $ctx ) );
		foreach ( $measure['overflow'] as $over ) {
			$i     = (int) $over['index'];
			$short = $client->json( self::SHORTEN_PROMPT, 'Тезис: ' . $points[ $i ]['text'] . "\nПредел: " . (int) $over['fits_chars'] . ' символов.', 300, 0.3 );
			if ( is_array( $short ) && ! empty( $short['text'] ) && mb_strlen( $short['text'] ) < mb_strlen( $points[ $i ]['text'] ) ) {
				$points[ $i ]['text'] = self::text( (string) $short['text'] );
			}
		}

		$all = get_post_meta( $post->ID, self::META, true );
		$all = is_array( $all ) ? $all : array();

		$all[ self::config_hash( $config ) ] = array(
			'points'   => $points,
			'modified' => $post->post_modified_gmt,
			'at'       => time(),
		);
		uasort( $all, function ( $a, $b ) {
			return (int) ( $b['at'] ?? 0 ) - (int) ( $a['at'] ?? 0 );
		} );
		update_post_meta( $post->ID, self::META, wp_slash( array_slice( $all, 0, self::MAX_ENTRIES, true ) ) );

		return $points;
	}

	private static function user_prompt( WP_Post $post, array $config, $count, $max_chars, $with_labels ) {
		$ctx   = array( 'post' => $post, 'config' => $config, 'llm' => null );
		$parts = array( 'Материал: ' . get_the_title( $post ) );

		$summary = WPTP_Template::resolve_chain( 'seo_description|short_description|excerpt', $ctx );
		if ( '' !== $summary ) {
			$parts[] = 'Кратко: ' . $summary;
		}

		$structure = self::from_structure( $post );
		if ( $structure['points'] ) {
			// Context, not the answer: the model writes its own points.
			$lines = array();
			foreach ( $structure['points'] as $p ) {
				$lines[] = ( '' !== $p['label'] ? $p['label'] . ': ' : '' ) . $p['text'];
			}
			$parts[] = "Пункты из материала:\n— " . implode( "\n— ", array_slice( $lines, 0, 12 ) );
		}

		$parts[] = "Текст (начало):\n" . WPTP_Template::truncate( WPTP_Template::content_text( $post ), 3000 );
		$parts[] = sprintf( 'Нужно пунктов: %d.', $count );
		$parts[] = sprintf( 'Предел длины text: %d символов.', $max_chars );
		$parts[] = $with_labels ? 'label заполняй: 1-3 слова.' : 'label оставляй пустой строкой.';
		$parts[] = 'Язык: ' . ( $config['llm_language'] ? $config['llm_language'] : 'русский' ) . '.';
		if ( '' !== trim( (string) $config['llm_prompt'] ) ) {
			$parts[] = trim( (string) $config['llm_prompt'] );
		}

		return implode( "\n\n", $parts );
	}

	/**
	 * Character budget per point, from the preset — the model is told this
	 * number, so it has to match what actually fits. A hint, not the layout.
	 */
	public static function char_budget( array $preset, $count ) {
		$is_list = 'list' === $preset['layout'];
		$columns = $is_list ? 1 : max( 1, (int) $preset['columns'] );
		$rows    = (int) ceil( $count / $columns );

		$padding = (int) $preset['padding'];
		$area_w  = (int) $preset['width'] - $padding * 2;
		$area_h  = (int) $preset['height'] - $padding * 2;

		if ( $preset['title_enabled'] ) {
			$area_h -= (int) round( $preset['title_size'] * 1.2 * 3 ) + (int) $preset['title_gap'];
		}
		if ( $preset['accent_enabled'] ) {
			$area_h -= (int) $preset['accent_height'] + (int) $preset['accent_gap'];
		}
		if ( $preset['footer_enabled'] ) {
			$area_h -= (int) round( $preset['footer_size'] * 1.3 ) + (int) $preset['footer_gap'];
		}

		$cell_w = (int) floor( ( $area_w - (int) $preset['gap_x'] * ( $columns - 1 ) ) / $columns );
		$cell_h = (int) floor( ( $area_h - (int) $preset['gap_y'] * ( $rows - 1 ) ) / max( 1, $rows ) );

		$pad    = $preset['plate_enabled'] ? (int) $preset['plate_padding'] : 0;
		$text_w = $cell_w - $pad * 2;
		$text_h = $cell_h - $pad * 2;

		if ( $is_list ) {
			$text_w -= (int) $preset['badge_size'] + (int) $preset['badge_gap'];
		} else {
			$text_h -= (int) $preset['badge_size'] + (int) $preset['badge_gap'];
		}
		if ( $preset['label_enabled'] ) {
			$text_h -= (int) round( $preset['label_size'] * 1.2 ) + (int) $preset['label_gap'];
		}

		$size  = (int) $preset['text_size'];
		$lines = max( 1, (int) floor( $text_h / max( 1, $size * (float) $preset['text_line_height'] ) ) );
		// ~0.52em per Cyrillic character — close enough for a hint.
		$per_line = max( 8, (int) floor( $text_w / max( 1, $size * 0.52 ) ) );

		return max( 40, min( 220, (int) floor( $per_line * $lines * 0.9 ) ) );
	}

	private static function failed_key( $post_id, array $config ) {
		return 'wptp_thesis_fail_' . $post_id . '_' . self::config_hash( $config );
	}

	// --------------------------------------------------------------- render

	/**
	 * Renders; whatever still overflows is dropped as a whole point, longest
	 * first — a missing point is honest, half a sentence is not.
	 *
	 * @return array{ok:bool,error:string,points:array,notes:array}
	 */
	public static function render_fitting( array $preset, array $points, $title, $footer, $background, $out_path ) {
		$notes   = array();
		$dropped = 0;

		while ( true ) {
			$result = WPTP_Infographic_Composer::compose( $preset, $points, $title, $footer, $background, $out_path );
			if ( ! $result['ok'] ) {
				return array( 'ok' => false, 'error' => $result['error'], 'points' => $points, 'notes' => $notes );
			}
			if ( empty( $result['overflow'] ) ) {
				if ( $dropped ) {
					$notes[] = 'убрано пунктов, не поместившихся в макет: ' . $dropped;
				}
				return array( 'ok' => true, 'error' => '', 'points' => $points, 'notes' => $notes );
			}
			if ( count( $points ) <= self::MIN_POINTS ) {
				// Keep the file: three points slightly over the limit are still
				// readable — the composer only went below the preset's minimum size.
				$notes[] = 'пункты не помещаются даже при минимальном кегле — проверьте пресет';
				return array( 'ok' => true, 'error' => '', 'points' => $points, 'notes' => $notes );
			}

			$longest = 0;
			foreach ( $points as $i => $point ) {
				if ( mb_strlen( $point['label'] . $point['text'] ) > mb_strlen( $points[ $longest ]['label'] . $points[ $longest ]['text'] ) ) {
					$longest = $i;
				}
			}
			array_splice( $points, $longest, 1 );
			++$dropped;
		}
	}
}
